class BlueComponent extends Component { render(){ return 'blue '+ super.render() } }
class RoundedBlueComponent extends Component { render(){ return 'rounded blue '+ super.render() } }

// Version A: small wrapper types
interface Stream { write(s: string): void }
class FileStream implements Stream { write(s: string) { console.log(s) } }
class Buffered implements Stream { constructor(private inner: Stream) {} write(s: string) { /* buffer then */ this.inner.write(s) } }
class Compressed implements Stream { constructor(private inner: Stream) {} write(s: string) { /* compress then */ this.inner.write(s) } }

// Version B: single class with feature flags
class StreamV2 { constructor(private buffered: boolean, private compressed: boolean) {} write(s: string) { if (this.compressed) s = compress(s); if (this.buffered) s = buffer(s); console.log(s) } }
